@font-face {
    font-family: 'Inter Variable';
    src: url('Inter-roman.var.woff2') format('woff2');
    font-weight: 100 900; /* Define the range of available weights */
    font-display: swap;
}

.hero-title {
    font-family: 'Inter Variable', sans-serif;
    font-variation-settings: 'wght' 700, 'wdth' 100; /* Specific weight and width */
    font-size: 3.5rem;
    line-height: 1.1;
}

.body-text {
    font-family: 'Inter Variable', sans-serif;
    font-variation-settings: 'wght' 400;
    font-size: 1.125rem;
    line-height: 1.6;
}

@media (max-width: 768px) {
    .hero-title {
        font-variation-settings: 'wght' 600, 'wdth' 90; /* Adjust for smaller screens */
        font-size: 2.5rem;
    }
}
